"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Evidence-reliability experiment, step 1 on dev (plan summarised in docs/iterations.md, 2026-11-23; the author
agreed). Exploratory: dev only, local systems only; no frozen file, setting or threshold changes.

Groups: the grounding package's dev matched groups (data/p1v4/runs/grounding/dev/groups.json): R-hear 200 x 3 versions,
S-move 72 x 4 (visitor silent). In every condition each version's non-audio inputs are version 2's (transcripts,
speaker tags, detector output), as in the package's matched conditions, so a group's versions differ only in the
audio and in the labels set below.
Labels:
  none    the package's "none": event-class detections (phone, doorbell, knock) removed (version 2's other detector
          output stays; the forward step counts the S-move groups whose version 2 output holds a footsteps or door
          detection in the window);
  fake    the package's "c0.99" on the R-hear windows (version 1's event class and span at 0.99 on every version) and
          "mv0.99" on the S-move windows (version 1's footsteps and door spans at 0.99 on every version);
  truth   new: event-class and movement-class detections removed, then each version's own real ones added at 0.99
          (event classes: one span per class from its first clip start to its last clip end, clipped at the point, as
          the package's groups; movement: p1v4_grounding.move_spans of that version). Like a notification sent by a
          smart doorbell or phone.
Sound: dclean (the dev windows themselves) and dnoise10 / dnoise20 / dnoise30 / dnoise40 (background noise louder by
that many dB, rendered by p1v4_noise_final.render with the frozen generator; dnoise10 already exists from the noise
rehearsal).
Systems (frozen, frozen thresholds from the rehearsal record): main system (2d), old head, 2c ears (8 s mean and max),
step 2 ears (ring-class labels decoupled), and the ears probe (R-hear: does it hear an event).
Check: dclean "none", "c0.99" and "mv0.99" must reproduce the package's stored dev forward (grounding/dev/l1_<cond>.npz)
score by score (old head and main system, max difference 1e-3), or the report stops.
Commands (repo root, .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_reliability_dev.py ...):
  render <variant> ...      e.g. render dnoise20 dnoise30 dnoise40
  forward                   every level x condition, batch 1 -> data/p1v4/runs/reliability/dev/<level>/l1_<cond>.npz
  report                    -> results/main_v04/reliability_step1_dev.json
"""
import collections
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_noise_final as NF  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/reliability/dev"
LEVELS = ("dclean", "dnoise10", "dnoise20", "dnoise30", "dnoise40")
NEW_DB = {"dnoise20": 20, "dnoise30": 30, "dnoise40": 40}
CONDS = ("none", "c0.99", "mv0.99", "truth")
SYSTEMS = ("2d", "old head", "2c ears", "step 2 ears")
TRUE_C = 0.99


def rehearsal_settings():
    import p1v4_freeze as FZ
    return json.load(open(FZ.REHEARSAL))["settings"]


# ------------------------------------------------------------------------------------------------ render

def render(variants):
    for v in variants:
        if v not in NEW_DB:
            raise SystemExit(f"{v}: only {sorted(NEW_DB)} are rendered here")
    NF.VARIANTS = dict(NF.VARIANTS, **NEW_DB)
    NF.frozen = lambda split: rehearsal_settings()          # dev only: the record's noise_db check covers 5 and 10
    NF.out_dir = lambda split, variant, *sub: _mk(os.path.join(OUT, variant, *sub))
    for v in variants:
        t0 = time.time()
        NF.render("dev", v)
        print(f"{v} rendered in {time.time() - t0:.0f} s", flush=True)


def _mk(d):
    os.makedirs(d, exist_ok=True)
    return d


# ------------------------------------------------------------------------------------------------ contexts

def truth_context(base):
    M = G.matched_context(base)

    class Truth(M):
        """Version 2's non-audio inputs; event and movement labels replaced by the version's own real ones at 0.99."""

        def point(self, r, k):
            g = self.gmap.get((r["unit"], r["version"], k))
            if g is None:
                return base.point(self, r, k)
            tr, sc, tags, snd = base.point(self, self.rows_by[(r["unit"], "2")], k)
            snd = [s for s in snd if s[0] not in G.EVENT and s[0] not in G.MOVE]
            t = g["t"]
            add = []
            for cls in G.EVENT:
                ev = [s for s in r["sources"] if s["kind"] == "clip" and s.get("cls") == cls and s["start"] < t]
                if ev:
                    s0, s1 = min(s["start"] for s in ev), min(max(s["end"] for s in ev), t)
                    if s1 > s0:
                        add.append((cls, round(s0, 3), round(s1, 3), TRUE_C))
            add += [(cls, a, b, TRUE_C) for cls, a, b in G.move_spans(r, t)]
            return tr, sc, tags, sorted(snd + add, key=lambda s: (s[1], s[0]))

        def situation(self, r, k, variant="full"):
            g = self.gmap.get((r["unit"], r["version"], k))
            if g is None:
                return base.situation(self, r, k, variant)
            tr, _, tags, snd = self.point(r, k)
            return G.SIT.build(self.rows_by[(r["unit"], "2")], k, tr, tags, snd, variant)

    return Truth


# ------------------------------------------------------------------------------------------------ forward

def forward():
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    import p1v4_readout as RO
    from p1v4_readout_2d import per_second
    D.gpu_guard()
    NF.patch_folders()
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    part_of = {g["unit"]: g["part"] for g in groups}
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    wins = [w for w in D.windows_of(rows, "dev") if (w["unit"], w["version"], w["k"]) in keys]
    paths = {"dclean": {(w["unit"], w["version"], w["k"]): w["path"] for w in wins}}
    for lv in LEVELS[1:]:
        if not os.path.exists(os.path.join(D.RENDER, f"dev_{lv}", "meta.jsonl")):
            raise SystemExit(f"dev_{lv} is not rendered")
        rv = D.load_rows(f"dev_{lv}")
        paths[lv] = {(w["unit"], w["version"], w["k"]): w["path"] for w in D.windows_of(rv, f"dev_{lv}")
                     if (w["unit"], w["version"], w["k"]) in keys}
        if set(paths[lv]) != keys:
            raise SystemExit(f"dev_{lv}: {len(keys - set(paths[lv]))} group windows missing")
    M, T = G.matched_context(C.Context), truth_context(C.Context)
    ctx = {c: (T if c == "truth" else M)("dev", groups, c, rows_by, final=False) for c in CONDS}
    # S-move groups whose version 2 output holds a footsteps or door detection in the window ("none" keeps it)
    note = collections.Counter()
    for g in groups:
        if g["part"] != "s_move":
            continue
        snd = C.Context.point(ctx["none"], rows_by[(g["unit"], "2")], g["k"])[3]
        mv = [s for s in snd if s[0] in G.MOVE and s[2] > g["t"] - D.WIN_S and s[1] < g["t"]]
        note["s_move groups"] += 1
        note["with a movement detection in version 2"] += bool(mv)
        note["with one >= 0.5"] += any(s[3] >= 0.5 for s in mv)
    _mk(OUT)
    json.dump(dict(note), open(f"{OUT}/none_movement_note.json", "w"), indent=1)
    print("none condition, S-move:", dict(note), flush=True)
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    for lv in LEVELS:
        for cond in CONDS:
            path = os.path.join(_mk(os.path.join(OUT, lv)), f"l1_{cond}.npz")
            if os.path.exists(path):
                print(f"{lv}/{cond}: exists, skipped", flush=True)
                continue
            items = []
            for w in wins:
                part = part_of[w["unit"]]
                if (cond == "c0.99" and part != "r_hear") or (cond == "mv0.99" and part != "s_move"):
                    continue
                r = rows_by[(w["unit"], w["version"])]
                text, asks = ctx[cond].situation(r, w["k"], "full")
                qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
                snd = [s for s in ctx[cond].point(r, w["k"])[3] if RO.in_window(s, w["t"])]
                items.append({"id": w["id"], "unit": w["unit"], "part": w["part"],
                              "path": paths[lv][(w["unit"], w["version"], w["k"])], "text": text,
                              "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                              "gold": [-1 if w["gold"].get(q) is None else
                                       int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs],
                              "real": RO.is_real(r, w["t"]), "conf": max([s[3] for s in snd], default=-1.0)})
            H, E, SM, SX, QW, QT, QG, PO = [], [], [], [], [], [], [], []
            t0 = time.time()
            with torch.no_grad():
                for i, it in enumerate(items):                       # batch 1, as the package
                    wave = torch.from_numpy(sf.read(it["path"], dtype="float32")[0])[None].cuda()
                    h, e, qw, po = RO.forward_states(model, wave, [it["text"]], [it["marker"]],
                                                     [[RO.TASK[q] for q in it["qs"]]])
                    sm, sx, _ = per_second(model.vt, wave)
                    H.append(h.astype(np.float16))
                    E.append(e.astype(np.float16))
                    SM.append(sm.astype(np.float16))
                    SX.append(sx.astype(np.float16))
                    QW.append(qw + i)
                    QT += it["qs"]
                    QG += it["gold"]
                    PO.append(po)
            np.savez(path, states=np.concatenate(H), ears=np.concatenate(E), sec_mean=np.concatenate(SM),
                     sec_max=np.concatenate(SX), q_win=np.concatenate(QW), q_task=np.array(QT), q_gold=np.array(QG),
                     p_old=np.concatenate(PO), ids=np.array([it["id"] for it in items]),
                     units=np.array([it["unit"] for it in items]), parts=np.array([it["part"] for it in items]),
                     real=np.array([it["real"] for it in items]), conf=np.array([it["conf"] for it in items]),
                     text_sha=np.array([G.sha(it["text"]) for it in items]))
            print(f"{lv}/{cond} done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)


# ------------------------------------------------------------------------------------------------ report

def scores_all(z, ro):
    import p1v4_conditional as CV
    import p1v4_readout as RO
    import p1v4_readout_2d as R2D
    sc = {"2d": R2D.scores_2d(z, R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"]), ro["2d"]),
          "old head": RO.scores_of(z, None, None), "2c ears": RO.scores_of(z, "ears", ro["2c"]),
          "step 2 ears": RO.scores_of(z, "ears", ro["s2"])}
    pe = CV.probe_p(z["ears"], ro["probe"])
    return sc, pe


def keyed(sc):
    return {(str(k[0]), str(k[1]), int(k[2])): v for k, v in sc.items()}


def questions(z, sc, th):
    """[(unit, part, version key, task, confidence, right)] of one system."""
    import p1v4_step0_confidence as S0
    out = []
    for j in range(len(z["q_task"])):
        g = int(z["q_gold"][j])
        if g < 0:
            continue
        i = int(z["q_win"][j])
        u, v, k = str(z["ids"][i]).split("|")
        q = str(z["q_task"][j])
        s = sc[(u, v, int(k))][q]
        t_q = th[0] if q == "S" else th[1]
        out.append((u, str(z["parts"][i]), (u, v, int(k)), q, S0.confidence(s, t_q), (s >= t_q) == bool(g)))
    return out


def report():
    import p1v4_readout as RO
    import p1v4_readout_2c as R2C
    import p1v4_readout_2d as R2D
    import p1v4_conditional as CV
    import p1v4_step0_confidence as S0
    st = rehearsal_settings()
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"]), "old head": (st["local"]["L1"]["th_s"],
                                                                         st["local"]["L1"]["th_r"])}
    for n in ("2c ears", "step 2 ears"):
        th[n] = (st["readouts"][n]["th_s"], st["readouts"][n]["th_r"])
    ro = {"s2": RO.load_readouts(), "2c": R2C.load_2c(), "2d": R2D.load_2d(),
          "probe": dict(np.load(f"{R}/readout/ears_probe.npz"))}
    res = {"split": "dev", "note": "exploratory (evidence-reliability step 1); plan docs/p1_v04_reliability_step1_plan.md",
           "thresholds": th, "check": {}, "ears_probe": {}, "cells": {}, "groups_all_right": {}}
    note = f"{OUT}/none_movement_note.json"
    res["none_movement_note"] = json.load(open(note)) if os.path.exists(note) else None
    # check: dclean none / c0.99 / mv0.99 reproduce the package's stored dev forward
    for cond in ("none", "c0.99", "mv0.99"):
        a = dict(np.load(f"{OUT}/dclean/l1_{cond}.npz"))
        b = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        sa, _ = scores_all(a, ro)
        sb, _ = scores_all(b, ro)
        worst = 0.0
        for n in ("2d", "old head"):
            ka, kb = keyed(sa[n]), keyed(sb[n])
            common = set(ka) & set(kb)
            if len(common) != len(ka):
                raise SystemExit(f"check {cond}: {len(set(ka) - common)} windows not in the stored forward")
            worst = max([worst] + [abs(ka[k][q] - kb[k][q]) for k in common for q in ka[k] if ka[k][q] is not None])
        res["check"][cond] = {"windows": len(common), "max_score_difference": worst}
        if worst > 1e-3:
            raise SystemExit(f"check failed: dclean {cond} differs from the stored forward by {worst}")
    for lv in LEVELS:
        for cond in CONDS:
            z = dict(np.load(f"{OUT}/{lv}/l1_{cond}.npz"))
            sc, pe = scores_all(z, ro)
            if cond == "none":                                   # does it hear an event (R-hear windows)
                rh = np.array([str(p) == "r_hear" for p in z["parts"]])
                heard = pe[rh] >= CV.EARS_CUT
                res["ears_probe"][lv] = float(np.mean(heard == z["real"][rh].astype(bool)))
            for n in SYSTEMS:
                qs = questions(z, keyed(sc[n]), th[n])
                for part in ("r_hear", "s_move"):
                    sel = [x for x in qs if x[1] == part]
                    if not sel:
                        continue
                    res["cells"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        S0.summary([x[4] for x in sel], [x[5] for x in sel])
                    ok = collections.defaultdict(lambda: True)
                    for x in sel:
                        ok[x[0]] = ok[x[0]] and bool(x[5])
                    res["groups_all_right"].setdefault(part, {}).setdefault(cond, {}).setdefault(n, {})[lv] = \
                        float(np.mean(list(ok.values())))
    os.makedirs("results/main_v04", exist_ok=True)
    json.dump(res, open("results/main_v04/reliability_step1_dev.json", "w"), indent=1)
    print("check:", json.dumps(res["check"]))
    print("none condition, S-move movement detections in version 2:", res["none_movement_note"])
    print("ears probe accuracy (R-hear, none):", {k: round(v, 3) for k, v in res["ears_probe"].items()})
    for part, cs in res["cells"].items():
        for cond, ns in cs.items():
            print(f"== {part} / {cond}: accuracy | group all-right | mean confidence | confident share | "
                  f"confident errors")
            for n, lvs in ns.items():
                cells = []
                for lv, x in lvs.items():
                    ga = res["groups_all_right"][part][cond][n][lv]
                    cells.append(f"{lv[1:]}: {x['accuracy']:.3f} {ga:.3f} {x['mean_conf']:.3f} "
                                 f"{x['confident_share']:.3f} " +
                                 ("n/a" if x["confident_error_rate"] is None else f"{x['confident_error_rate']:.3f}"))
                print(f"  {n:12s} " + " | ".join(cells))
    print("-> results/main_v04/reliability_step1_dev.json")


if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else ""
    if cmd == "render":
        render(sys.argv[2:])
    elif cmd == "forward":
        forward()
    elif cmd == "report":
        report()
    else:
        raise SystemExit(__doc__)
